// Estrutura de pastas sugerida
// src/
//   models/
//     Task.js            -> classe Task (dados e validações da entidade)
//     TaskManager.js      -> classe TaskManager (coleção e regras de negócio)
//   errors/
//     TaskErrors.js        -> TaskError, ValidationError, TaskNotFoundError, StorageError
//   storage/
//     storage.js           -> loadTasks / saveTasks (localStorage ou fs/promises)
//   services/
//     network.js           -> simulateRequest (Promise com atraso e falhas simuladas)
//   index.js                -> ponto de entrada que junta tudo

import { TaskManager } from './models/TaskManager.js';
import { loadTasks, saveTasks } from './storage/storage.js';
import { TaskNotFoundError, ValidationError, StorageError } from './errors/TaskErrors.js';

class TaskError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = this.constructor.name;
  }
}

class ValidationError extends TaskError {}

class TaskNotFoundError extends TaskError {
  constructor(id) {
    super(`Tarefa com id "${id}" não foi encontrada.`);
    this.id = id;
  }
}

class StorageError extends TaskError {}

let proximoId = 1;

class Task {
  #createdAt = new Date();

  constructor({ title, description = '', priority = 'normal', tags = [] }) {
    if (!title) throw new ValidationError('O título da tarefa é obrigatório.');
    this.id = String(proximoId++);
    this.title = title;
    this.description = description;
    this.priority = priority;
    this.tags = new Set(tags);
    this.done = false;
  }

  get createdAt() {
    return this.#createdAt;
  }
}

class TaskManager {
  #tasks = new Map();

  add(dados) {
    const tarefa = new Task(dados);
    this.#tasks.set(tarefa.id, tarefa);
    return tarefa;
  }

  getById(id) {
    const tarefa = this.#tasks.get(id);
    if (!tarefa) throw new TaskNotFoundError(id);
    return tarefa;
  }
}

const CHAVE_ARMAZENAMENTO = 'gestor-tarefas:v1';

function loadTasks() {
  try {
    const dados = localStorage.getItem(CHAVE_ARMAZENAMENTO);
    return dados ? JSON.parse(dados) : [];
  } catch (erro) {
    throw new StorageError('Não foi possível ler as tarefas guardadas.', { cause: erro });
  }
}

function saveTasks(tarefas) {
  try {
    localStorage.setItem(CHAVE_ARMAZENAMENTO, JSON.stringify(tarefas));
  } catch (erro) {
    throw new StorageError('Não foi possível guardar as tarefas.', { cause: erro });
  }
}

function simulateRequest(payload, { delay = 400, failRate = 0.15 } = {}) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Math.random() < failRate) {
        reject(new StorageError('Falha simulada ao sincronizar com o servidor.'));
      } else {
        resolve(payload);
      }
    }, delay);
  });
}

async function sincronizarTarefas(manager) {
  const dados = manager.list().map((tarefa) => tarefa.toJSON?.() ?? tarefa);
  try {
    const resposta = await simulateRequest(dados);
    saveTasks(resposta);
    return resposta;
  } catch (erro) {
    if (erro instanceof StorageError) {
      console.error('Sincronização falhou:', erro.message);
    }
    throw erro;
  }
}

