import { ValidationError } from '../errors/TaskErrors.js';

let proximoId = 1;

export class Task {
  #createdAt;

  constructor({ title, description = '', priority = 'normal', tags = [] }) {
    if (!title || typeof title !== 'string') {
      throw new ValidationError('O título da tarefa é obrigatório.');
    }
    this.id = String(proximoId++);
    this.title = title;
    this.description = description;
    this.priority = priority;
    this.tags = new Set(tags);
    this.done = false;
    this.#createdAt = new Date();
  }

  get createdAt() {
    return this.#createdAt;
  }

  toggle() {
    this.done = !this.done;
    return this.done;
  }

  toJSON() {
    const { id, title, description, priority, done } = this;
    return {
      id, title, description, priority, done,
      tags: [...this.tags],
      createdAt: this.#createdAt.toISOString(),
    };
  }
}

