import { StorageError } from '../errors/TaskErrors.js';

export function simulateRequest(payload, { delay = 400, failRate = 0.1 } = {}) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Math.random() < failRate) {
        reject(new StorageError('Falha simulada de rede ao sincronizar tarefas.'));
        return;
      }
      resolve(payload);
    }, delay);
  });
}

