import { Task } from './Task.js';
import { TaskNotFoundError } from '../errors/TaskErrors.js';
import { simulateRequest } from '../services/network.js';

export class TaskManager {
  #tasks = new Map();

  add(dados) {
    const tarefa = new Task(dados);
    this.#tasks.set(tarefa.id, tarefa);
    return tarefa;
  }

  getById(id) {
    const tarefa = this.#tasks.get(id);
    if (!tarefa) throw new TaskNotFoundError(id);
    return tarefa;
  }

  toggle(id) {
    const tarefa = this.getById(id);
    tarefa.toggle();
    return tarefa;
  }

  remove(id) {
    if (!this.#tasks.delete(id)) throw new TaskNotFoundError(id);
  }

  list({ apenasPendentes = false } = {}) {
    const todas = [...this.#tasks.values()];
    return apenasPendentes ? todas.filter(({ done }) => !done) : todas;
  }

  async sincronizar() {
    const dados = this.list().map((tarefa) => tarefa.toJSON());
    return simulateRequest(dados);
  }
}

