class TaskError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = this.constructor.name;
  }
}
class ValidationError extends TaskError {}

const PRIORIDADES_VALIDAS = new Set(['baixa', 'normal', 'alta']);

function validarPrioridade(prioridade) {
  if (!PRIORIDADES_VALIDAS.has(prioridade)) {
    throw new ValidationError(
      `Prioridade "${prioridade}" inválida. Use: ${[...PRIORIDADES_VALIDAS].join(', ')}.`
    );
  }
  return prioridade;
}

class Task {
  constructor({ title, description = '', priority = 'normal', tags = [] }) {
    if (!title) throw new ValidationError('O título da tarefa é obrigatório.');
    this.title = title;
    this.description = description;
    this.priority = validarPrioridade(priority);
    this.tags = new Set(tags);
    this.done = false;
  }
}

// new Task({ title: 'Estudar', priority: 'urgente' }) lança ValidationError

function createFilterByTag(tasks) {
  const indice = new Map();

  for (const tarefa of tasks) {
    for (const tag of tarefa.tags) {
      if (!indice.has(tag)) indice.set(tag, []);
      indice.get(tag).push(tarefa);
    }
  }

  return function filtrarPorTag(tag) {
    return indice.get(tag) ?? [];
  };
}

