const PESO_PRIORIDADE = new Map([
  ['baixa', 0],
  ['normal', 1],
  ['alta', 2],
]);

function ordenarTarefas(tarefas, criterio = 'data') {
  const copia = [...tarefas];

  if (criterio === 'prioridade') {
    return copia.sort((a, b) => PESO_PRIORIDADE.get(b.priority) - PESO_PRIORIDADE.get(a.priority));
  }
  if (criterio === 'data') {
    return copia.sort((a, b) => a.createdAt - b.createdAt);
  }
  throw new ValidationError(`Critério de ordenação "${criterio}" desconhecido.`);
}

