async function sincronizarComRetries(manager, tentativasMaximas = 3) {
  let ultimoErro;

  for (let tentativa = 1; tentativa <= tentativasMaximas; tentativa++) {
    try {
      return await manager.sincronizar();
    } catch (erro) {
      if (!(erro instanceof StorageError)) throw erro;
      ultimoErro = erro;
      const atraso = 200 * 2 ** (tentativa - 1);
      console.warn(`Tentativa ${tentativa} falhou. Nova tentativa em ${atraso}ms.`);
      await esperar(atraso);
    }
  }

  throw ultimoErro;
}

class EventBus {
  #ouvintes = new Map();

  on(evento, callback) {
    if (!this.#ouvintes.has(evento)) this.#ouvintes.set(evento, new Set());
    this.#ouvintes.get(evento).add(callback);
    return () => this.#ouvintes.get(evento)?.delete(callback);
  }

  emit(evento, dados) {
    for (const callback of this.#ouvintes.get(evento) ?? []) {
      callback(dados);
    }
  }
}

class TaskManager {
  #tasks = new Map();
  #bus = new EventBus();

  on(evento, callback) {
    return this.#bus.on(evento, callback);
  }

  add(dados) {
    const tarefa = new Task(dados);
    this.#tasks.set(tarefa.id, tarefa);
    this.#bus.emit('tarefa:adicionada', tarefa);
    return tarefa;
  }

  remove(id) {
    const tarefa = this.getById(id);
    this.#tasks.delete(id);
    this.#bus.emit('tarefa:removida', tarefa);
  }

  toggle(id) {
    const tarefa = this.getById(id);
    tarefa.toggle();
    this.#bus.emit('tarefa:alterada', tarefa);
    return tarefa;
  }

  getById(id) {
    const tarefa = this.#tasks.get(id);
    if (!tarefa) throw new TaskNotFoundError(id);
    return tarefa;
  }

  list() {
    return [...this.#tasks.values()];
  }
}

const manager = new TaskManager();
for (const evento of ['tarefa:adicionada', 'tarefa:removida', 'tarefa:alterada']) {
  manager.on(evento, () => saveTasks(manager.list().map((t) => t.toJSON())));
}
